"use strict";(self.webpackChunkwv_documentation=self.webpackChunkwv_documentation||[]).push([[292],{5824(e,n,t){t.r(n),t.d(n,{assets:()=>u,contentTitle:()=>d,default:()=>c,frontMatter:()=>a,metadata:()=>r,toc:()=>o});const r=JSON.parse('{"id":"method","title":"Methode","description":"Die Arbeit verfolgt das Ziel, den Forschungsstand zu Zustandstransparenz in","source":"@site/content/method.md","sourceDirName":".","slug":"/method","permalink":"/wv-documentation/method","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"title":"Methode","sidebar_position":3},"sidebar":"tutorialSidebar","previous":{"title":"Startseite","permalink":"/wv-documentation/"},"next":{"title":"Systematische Literaturanalyse","permalink":"/wv-documentation/literature-analysis"}}');var i=t(2540),s=t(3023);const a={title:"Methode",sidebar_position:3},d="Methode",u={},o=[{value:"Qualit\xe4t und Grenzen",id:"qualit\xe4t-und-grenzen",level:2}];function h(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"methode",children:"Methode"})}),"\n",(0,i.jsx)(n.p,{children:"Die Arbeit verfolgt das Ziel, den Forschungsstand zu Zustandstransparenz in\nConversational-AI-Systemen (CAI) systematisch aufzuarbeiten. Da es sich um ein\ndynamisches Forschungsfeld handelt und der Zustandsbegriff uneinheitlich\nverwendet wird, wurde ein explorativer Zugang gew\xe4hlt. Dieser orientiert sich\nan vom Brocke et al. (2009) sowie an Webster und Watson (2002).\nDie Wahl des explorativen Vorgehens begr\xfcndet sich zudem durch die Breite und\ndas rasche Wachstum des noch jungen Forschungsfeldes. Bislang liegt keine\nklassifizierte \xdcbersicht dar\xfcber vor, welche Interaktionszust\xe4nde und\n-\xfcberg\xe4nge in Conversational-AI-Systemen unterschieden werden k\xf6nnen. Die\nexplorative Analyse erm\xf6glicht daher zun\xe4chst eine offene Bestandsaufnahme und\nschafft die Grundlage f\xfcr ihre systematische Ordnung und weitere Untersuchung."}),"\n",(0,i.jsx)(n.p,{children:"Die Untersuchung in Form einer systematischen Literaturanalyse folgt einer \xfcbergeordneten Forschungsfrage, die zun\xe4chst\nerfasst, welche Interaktionszust\xe4nde und -\xfcberg\xe4nge in der Forschung zu\nConversational AI als relevant f\xfcr die Transparenzgestaltung diskutiert\nwerden (RQ1). Darauf aufbauend wird untersucht, anhand welcher Merkmale sich\ndiese Zustands\xfcberg\xe4nge systematisch unterscheiden und beschreiben lassen\n(RQ1.1) und wie die Literatur den Transparenzbedarf in ausgew\xe4hlten\nAnwendungsdom\xe4nen begr\xfcndet (RQ1.2). Das Vorgehen f\xfchrt damit von einer deskriptiven Bestandsaufnahme \xfcber die Ableitung von Merkmalen bis zur\nEinordnung des dom\xe4nenspezifischen Transparenzbedarfs. Als Ergebnis entstehen eine konzeptzentrierte Synthese und eine Taxonomie der in der Forschung diskutierten Zust\xe4nde und \xdcberg\xe4nge in der Interaktion mit CAI-Systemen."}),"\n",(0,i.jsxs)(n.p,{children:["Das methodische Vorgehen umfasst eine strukturierte Literaturrecherche, die\nPr\xfcfung und Auswahl der relevanten Publikationen sowie deren systematische\nAuswertung. Die eingeschlossenen Arbeiten wurden einheitlich dokumentiert,\nvergleichend analysiert und im Hinblick auf Interaktionszust\xe4nde,\nZustands\xfcberg\xe4nge und Transparenzanforderungen ausgewertet. Dabei wurden\nwiederkehrende Konzepte und Merkmale herausgearbeitet, in thematisch passende Cluster zusammengefasst\nund zu einer konzeptzentrierten Synthese sowie einer tabellarischen Taxonomie\nschlie\xdflich zusammengef\xfchrt. Die konkreten Suchstrategien, Auswahlkriterien und Schritte\nder Literaturanalyse werden auf der entsprechenden ",(0,i.jsx)(n.a,{href:"literature-analysis",children:"Seite zur Literaturanalyse"}),"\nausgef\xfchrt."]}),"\n",(0,i.jsxs)("figure",{children:[(0,i.jsx)("img",{src:"img/method-vorgehen.svg",alt:"Ablauf des methodischen Vorgehens von den Forschungsfragen \xfcber Recherche, Auswahl, Dokumentation und Auswertung zur Synthese und Taxonomie."}),(0,i.jsx)("figcaption",{children:"Abbildung 1: Aufgaben und Ablauf des methodischen Vorgehens."})]}),"\n",(0,i.jsx)(n.h2,{id:"qualit\xe4t-und-grenzen",children:"Qualit\xe4t und Grenzen"}),"\n",(0,i.jsxs)(n.p,{children:["Die Vergleichbarkeit wird erh\xf6ht, indem technische Beitr\xe4ge, Reviews, Frameworks, Prototypen und empirische Studien als unterschiedliche Evidenztypen mit jeweils eigener Aussagekraft ausgewiesen werden: Technische Beitr\xe4ge belegen vor allem die Machbarkeit oder Existenz eines Zustands, Reviews b\xfcndeln und gewichten vorhandene Befunde, Frameworks strukturieren Begriffe und Beziehungen, Prototypen veranschaulichen konkrete Umsetzungen, und empirische Studien liefern Beobachtungen zu Nutzung und Wirkung. Aussagen \xfcber Nutzerwirkungen werden daher nicht automatisch auf alle Systemtypen \xfcbertragen. Eine technische Implementierung belegt beispielsweise die Existenz eines Zustands, aber nicht ohne Weiteres dessen Verst\xe4ndlichkeit oder Wirkung auf Vertrauen.\nDie Vielfalt der einbezogenen Publikationen, von Reviews \xfcber Feldstudien bis\nhin zu erprobten Prototypen, bildet unterschiedliche Perspektiven und\nEvidenzformen ab und stellt dadurch eine m\xf6glichst gute Ann\xe4herung an den\naktuellen Stand der Forschung und Technik dar. Konkrete Beispiele unter den im Rahmen der Literatur entwickelten und erprobten Prototypen sind auf der ",(0,i.jsx)(n.a,{href:"/wv-documentation/artifacts",children:"Seite der Artefakte"})," zu finden."]}),"\n",(0,i.jsx)(n.p,{children:"Die Synthese ist au\xdferdem durch die Auswahl der Datenbanken, Suchbegriffe, Publikationsjahre und die subjektive Bewertung von Relevanz begrenzt. Die Ergebnisse sind als methodisch begr\xfcndete Kartierung des Forschungsfeldes zu lesen, nicht als vollst\xe4ndige Erfassung jeder Arbeit zu Conversational AI. Diese Begrenzung wird bei der Ableitung von Forschungs- und Anwendungspotenzialen ber\xfccksichtigt."})]})}function c(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},3023(e,n,t){t.d(n,{R:()=>a,x:()=>d});var r=t(3696);const i={},s=r.createContext(i);function a(e){const n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);